const items = $input.all();
const orderIds = items.map(i => i.json.shopify_order_id);

const fragments = orderIds.map((id, idx) => {
  const gid = "gid://shopify/Order/" + id;
  return `o${idx}: order(id: "${gid}") {
    id
    name
    customerJourneySummary {
      ready
      customerOrderIndex
      daysToConversion
      momentsCount { count precision }
      firstVisit {
        occurredAt sourceType landingPage referrerUrl
        utmParameters { source medium campaign content term }
        marketingEvent { id }
      }
      lastVisit {
        occurredAt sourceType landingPage referrerUrl
        utmParameters { source medium campaign content term }
      }
      moments(first: 50) {
        edges {
          node {
            ... on CustomerVisit {
              id occurredAt sourceType landingPage referrerUrl
              utmParameters { source medium campaign content term }
            }
          }
        }
      }
    }
  }`;
}).join("\n");

const query = "query BatchJourneys {\n" + fragments + "\n}";

return [{ json: { query, batch_size: orderIds.length, order_ids: orderIds } }];

const resp = $input.first().json;
if (resp.errors) {
  return [{ json: { journeys_data: [], errors: resp.errors, batch_failed: true } }];
}

const data = resp.data || {};
const journeys = [];

for (const key of Object.keys(data)) {
  const order = data[key];
  if (!order) continue;

  const idMatch = order.id.match(/Order\/(\d+)/);
  const shopify_order_id = idMatch ? idMatch[1] : null;
  if (!shopify_order_id) continue;

  const j = order.customerJourneySummary;

  if (!j) {
    journeys.push({ shopify_order_id, ready: false, moments: [] });
    continue;
  }

  const fv = j.firstVisit;
  const lv = j.lastVisit;
  const moments = (j.moments?.edges || []).map(e => e.node);

  journeys.push({
    shopify_order_id,
    customer_order_index: j.customerOrderIndex,
    days_to_conversion: j.daysToConversion,
    moments_count: j.momentsCount?.count,
    moments_precision: j.momentsCount?.precision,
    ready: j.ready === true,

    first_visit_at: fv?.occurredAt || null,
    first_visit_source: fv?.utmParameters?.source || null,
    first_visit_medium: fv?.utmParameters?.medium || null,
    first_visit_campaign: fv?.utmParameters?.campaign || null,
    first_visit_content: fv?.utmParameters?.content || null,
    first_visit_term: fv?.utmParameters?.term || null,
    first_visit_landing: fv?.landingPage || null,
    first_visit_referrer: fv?.referrerUrl || null,
    first_visit_source_type: fv?.sourceType || null,
    first_visit_marketing_event_id: fv?.marketingEvent?.id || null,

    last_visit_at: lv?.occurredAt || null,
    last_visit_source: lv?.utmParameters?.source || null,
    last_visit_medium: lv?.utmParameters?.medium || null,
    last_visit_campaign: lv?.utmParameters?.campaign || null,
    last_visit_content: lv?.utmParameters?.content || null,
    last_visit_term: lv?.utmParameters?.term || null,
    last_visit_landing: lv?.landingPage || null,
    last_visit_referrer: lv?.referrerUrl || null,
    last_visit_source_type: lv?.sourceType || null,

    raw_payload: j,

    moments: moments.map(m => ({
      shopify_visit_id: m.id,
      occurred_at: m.occurredAt,
      utm_source: m.utmParameters?.source || null,
      utm_medium: m.utmParameters?.medium || null,
      utm_campaign: m.utmParameters?.campaign || null,
      utm_content: m.utmParameters?.content || null,
      utm_term: m.utmParameters?.term || null,
      landing_page: m.landingPage || null,
      referrer_url: m.referrerUrl || null,
      source_type: m.sourceType || null,
      marketing_event_id: null
    }))
  });
}

return [{ json: { journeys_data: journeys, batch_failed: false } }];

